#!/usr/bin/env bun
// Writes one module per locale into src/lib/translations-generated/ from the
// aggregate in src/lib/translations.ts — every key of the locale laid over
// English, so a key a locale lacks still reads in English, exactly as the
// I18nProvider merged them at runtime.
//
// Why: `translations.ts` and the tables it merges keep all ten locales in the
// same modules, so the bundler could only ship them as ONE 3.5 MB chunk that
// every desktop and /login load parsed for the one locale it renders. The
// generated files are what `src/lib/translation-chunks.ts` imports, one chunk
// per locale, and they are COMMITTED: `src/tests/unit/translation-chunks.test.ts`
// fails when they drift from the source tables, and this script is the fix
// (`bun run gen:translations`). Run it after any change to a translation table.
//
// Modules rather than JSON, one entry per line: the public-hygiene check reads
// every added line, and a string that names an account's home (a translation
// that shows an example path) needs its `public-hygiene: allow <why>` marker
// on that line — JSON has nowhere to put one. The marker is written here, by
// the scanner's own rule, so the generated file passes exactly where the
// source table does.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { translations } from "../src/lib/translations";
import { LANGUAGES, type Locale } from "../src/lib/i18n";
import { inspectLine } from "./public-hygiene.mjs";

const outDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "src", "lib", "translations-generated");
fs.mkdirSync(outDir, { recursive: true });

export function localeTable(locale: Locale): Record<string, string> {
  const en = translations.en ?? {};
  const active = translations[locale] ?? en;
  const merged: Record<string, string> = { ...en, ...active };
  return Object.fromEntries(Object.keys(merged).sort().map((k) => [k, merged[k]]));
}

const ALLOW = "public-hygiene: allow an example path in a translation, the same string as in src/lib/*translations*.ts";

export function renderModule(locale: Locale, table: Record<string, string>): string {
  const lines = [
    `// GENERATED by scripts/gen-translation-chunks.ts from src/lib/translations.ts — do not edit.`,
    `// Run \`bun run gen:translations\` after changing a translation table (the unit test says so too).`,
    `// Locale "${locale}" laid over English, one chunk of its own; read by src/lib/translation-chunks.ts.`,
    `const table: Record<string, string> = {`,
  ];
  for (const [k, v] of Object.entries(table)) {
    let line = `  ${JSON.stringify(k)}: ${JSON.stringify(v)},`;
    const found = inspectLine(line) as { categories: string[] };
    if (found.categories.length) line += ` // ${ALLOW}`;
    lines.push(line);
  }
  lines.push(`};`, `export default table;`, ``);
  return lines.join("\n");
}

let changed = 0;
for (const { code } of LANGUAGES) {
  const file = path.join(outDir, `${code}.ts`);
  const next = renderModule(code, localeTable(code));
  // Read, never "exists then read": the file is only ever compared and rewritten.
  let prev: string | null = null;
  try { prev = fs.readFileSync(file, "utf8"); } catch { prev = null; }
  if (prev !== next) { fs.writeFileSync(file, next); changed++; }
  // The JSON shape an earlier version wrote; gone if it is there.
  try { fs.unlinkSync(path.join(outDir, `${code}.json`)); } catch { /* none */ }
}
console.log(`[gen-translation-chunks] ${LANGUAGES.length} locales, ${changed} file(s) written to ${path.relative(process.cwd(), outDir)}`);
